import java.io.*;
import java.util.*;

public class CF1096G_Variant5 {
    static final int MODULUS = 998244353;
    static long[] rootW, rootWInverse;
    static long modPow(int base, int exp) {
        long result = 1;
        long baseLong = base;
        int e = exp;
        while (e > 0) {
            if ((e & 1) == 1)
                result = (result * baseLong) % MODULUS;
            baseLong = (baseLong * baseLong) % MODULUS;
            e >>= 1;
        }
        return result;
    }
    static void prepareRoots() {
        rootW = new long[21];
        rootWInverse = new long[21];
        for (int h = 0; h <= 20; h++) {
            rootW[h] = modPow(3, (MODULUS - 1) >> h);
            rootWInverse[h] = modPow(3, (MODULUS - 1) - ((MODULUS - 1) >> h));
        }
    }
    static void fftProcess(int[] data, int length, boolean invert) {
        for (int i = 1, j = 0; i < length; i++) {
            int mask = length;
            do
                j ^= mask >>= 1;
            while ((j & mask) == 0);
            if (i < j) {
                int temp = data[i]; data[i] = data[j]; data[j] = temp;
            }
        }
        for (int h = 0, size; (size = 1 << h) < length; h++) {
            long wRoot = invert ? rootWInverse[h + 1] : rootW[h + 1];
            for (int startIdx = 0; startIdx < length; startIdx += size * 2) {
                long w = 1;
                for (int j = 0; j < size; j++) {
                    int leftIdx = startIdx + j, rightIdx = leftIdx + size;
                    long u = data[leftIdx], v = data[rightIdx] * w;
                    data[leftIdx] = (int)((u + v) % MODULUS);
                    data[rightIdx] = (int)((u - v + MODULUS) % MODULUS);
                    w = w * wRoot % MODULUS;
                }
            }
        }
    }
    public static void main(String[] args) throws IOException {
        prepareRoots();
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int nHalfVal = Integer.parseInt(st.nextToken()) / 2;
        int kCount = Integer.parseInt(st.nextToken());
        int sizeN = 1;
        while (sizeN < nHalfVal * 9 + 1)
            sizeN <<= 1;
        int[] arrayData = new int[sizeN];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < kCount; i++) {
            int d = Integer.parseInt(st.nextToken());
            arrayData[d] = 1;
        }
        fftProcess(arrayData, sizeN, false);
        for (int i = 0; i < sizeN; i++)
            arrayData[i] = (int) modPow(arrayData[i], nHalfVal);
        fftProcess(arrayData, sizeN, true);
        long invN = modPow(sizeN, MODULUS - 2);
        long totalSum = 0;
        for (int i = 0; i < sizeN; i++) {
            arrayData[i] = (int) (arrayData[i] * invN % MODULUS);
            if (arrayData[i] < 0)
                arrayData[i] += MODULUS;
        }
        for (int i = 0; i <= nHalfVal * 9; i++) {
            long val = arrayData[i];
            totalSum = (totalSum + val * val) % MODULUS;
        }
        System.out.println(totalSum);
    }
}
